package com.quincaisoft.documents.application;
import com.quincaisoft.documents.api.DocumentWorkspace.*;
import java.util.Set;
/** Deterministic, escaped EN/FR HTML from immutable data. Browser/PDF/printer certification is separate. */
public final class DocumentHtml {
 private DocumentHtml(){}
 public static String paper(String paper){if(paper==null||!Set.of("A4","58mm","80mm").contains(paper))throw new IllegalArgumentException("Paper must be A4, 58mm or 80mm");return paper;}
 public static String render(Capture capture,String profile,boolean duplicate){paper(profile);var c=capture.content();var d=c.source();boolean fr=c.issuer().locale().equals("fr");String width=profile.equals("A4")?"190mm":profile.equals("58mm")?"48mm":"70mm";
  var h=new StringBuilder("<!doctype html><html lang=\"").append(fr?"fr":"en").append("\"><head><meta charset=\"utf-8\"><title>").append(esc(c.template().title())).append("</title><style>@page{size:").append(profile.equals("A4")?"A4":profile+" auto").append(";margin:5mm}body{font:12px sans-serif;max-width:").append(width).append(";margin:12px auto;color:#142934}table{width:100%;border-collapse:collapse;table-layout:fixed}td,th{padding:5px;border-bottom:1px solid #ddd;text-align:left;overflow-wrap:anywhere}h1{font-size:20px}.mark{font-weight:bold}small{overflow-wrap:anywhere}@media print{body{margin:0}}</style></head><body><h1>").append(esc(c.issuer().issuerName())).append("</h1><p>").append(esc(c.issuer().issuerAddress())).append("<br>").append(esc(c.issuer().registrationNumber())).append("</p><h2>").append(esc(fr?c.template().titleFr():c.template().title())).append("</h2>");
  if(duplicate)h.append("<p class=\"mark\">DUPLICATE / COPIE</p>");h.append("<p>").append(fr?"Capture de source — non certifiée DGI":"Source capture — not DGI certified").append("</p><p>").append(esc(d.sourceReference())).append(" · ").append(d.businessDate()==null?"":d.businessDate()).append(" · ").append(esc(d.sourceStatus())).append("</p><p>").append(esc(d.party())).append("</p><table><thead><tr>");for(var col:d.columns()){var labels=col.split("\\|",2);h.append("<th>").append(esc(fr&&labels.length>1?labels[1]:labels[0])).append("</th>");}h.append("</tr></thead><tbody>");for(var row:d.rows()){h.append("<tr>");for(var value:row)h.append("<td>").append(esc(value)).append("</td>");h.append("</tr>");}h.append("</tbody></table>");if(!d.totalXaf().isEmpty())h.append("<h3>Total: ").append(esc(d.totalXaf())).append(" XAF</h3>");return h.append("<p>").append(esc(d.basis())).append("</p><small>").append(esc(c.templateVersion())).append(" · ").append(c.capturedAt()).append("<br>SHA-256: ").append(capture.sha256()).append("</small></body></html>").toString();
 }
 private static String esc(String s){return DefaultDocumentService.esc(s==null?"":s);}
}
